def _machine_table(doc, scope_title: str):
    """Return the machine table node for the given scope, or None."""
    for child in children(doc, node_by_title(doc, scope_title)):
        if child['kind'] == 'table' and child['title'].endswith(': Machines'):
            return child
    return None


def _task_log_table(doc, scope_title: str):
    """Return the task log table node for the given scope, or None."""
    for child in children(doc, node_by_title(doc, scope_title)):
        if child['kind'] == 'table' and child['title'].endswith(': Task log'):
            return child
    return None


def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return all distinct entities that appear in the scope."""
    ents: Dict[str, str] = {}

    # Machines
    mt = _machine_table(doc, scope)
    if mt:
        for ridx, row in table_rows(mt):
            mid = row.get('machine')
            if mid:
                ents[mid] = f"machine {mid}"

    # Tasks and jobs
    tlt = _task_log_table(doc, scope)
    if tlt:
        for ridx, row in table_rows(tlt):
            tid = row.get('task')
            jid = row.get('job')
            if tid:
                ents[tid] = f"task {tid}"
                if jid:
                    ents[jid] = f"job {jid}"

    return [{"id": k, "description": v} for k, v in sorted(ents.items())]


def recorded_end(doc: Dict[str, Any], scope: str) -> Any:
    """Maximum time value recorded in the task log."""
    tlt = _task_log_table(doc, scope)
    if not tlt:
        return None
    times = []
    for ridx, row in table_rows(tlt):
        t_val = row.get('time')
        if t_val is None or t_val == '-':
            continue
        try:
            times.append(float(t_val))
        except ValueError:
            continue
    return max(times) if times else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All inputs that the process receives from outside."""
    out: List[Dict[str, Any]] = []

    # Machine definitions (capacity & fail/return times)
    mt = _machine_table(doc, scope)
    if mt:
        node_id = mt['node_id']
        for ridx, row in table_rows(mt):
            mid = row.get('machine')
            if not mid:
                continue
            fail_t = row.get('fails at')
            ret_t = row.get('returns at')
            inp = {
                "id": mid,
                "time": float(fail_t) if fail_t not in ("-", None) else None,
                "kind": "machine",
                "entities": [mid],
                "fields": {
                    "CPU": float(row.get('CPU', 0)),
                    "memory": float(row.get('memory', 0)),
                    "fails at": float(fail_t) if fail_t not in ("-", None) else None,
                    "returns at": float(ret_t) if ret_t not in ("-", None) else None,
