# 3. Examine task wait times at start events in a sample window
def sample_wait_times(doc, sample_window='Cell window 04'):
    tl = _find_table(doc, sample_window, ': Task log')
    if not tl:
        return
    # Map submission time per task id
    sub_times = {}
    for ridx, row in table_rows(tl):
        if row.get('event') == 'submit':
            sub_times[row.get('task')] = _parse_num(row.get('time')) or 0.0
    # Find first start times
    start_times = {}
    for ridx, row in table_rows(tl):
        if row.get('event') == 'start':
            start_times[row.get('task')] = _parse_num(row.get('time')) or 0.0
    # Compute wait
    waits = []
    for tid, s in sub_times.items():
        if tid in start_times:
            waits.append(start_times[tid] - s)
    if waits:
        print(f"{sample_window} wait stats: min={min(waits):.1f} sec, max={max(waits):.1f} sec, avg={sum(waits)/len(waits):.1f} sec")
    else:
        print(f"{sample_window} no start events found")

sample_wait_times(doc)

# 4. Distribution of task run times for a window
def run_time_histogram(doc, scope, bins=5):
    tl = _find_table(doc, scope, ': Task log')
    if not tl:
        return
    runtimes = []
    for ridx, row in table_rows(tl):
        if row.get('event') == 'submit':
            rt = _parse_num(row.get('run time'))
            if rt is not None:
                runtimes.append(rt)
    if not runtimes:
        print(f"{scope} no runtimes")
        return
    min_rt, max_rt = min(runtimes), max(runtimes)
    bin_size = (max_rt - min_rt) / bins
    bins_edges = [min_rt + i * bin_size for i in range(bins+1)]
    counts = [0] * bins
    for rt in runtimes:
        for i in range(bins):
            if bins_edges[i] <= rt < bins_edges[i+1] or (i == bins-1 and rt == bins_edges[i+1]):
                counts[i] += 1
                break
    print(f"{scope} run time distribution (bins of size {bin_size:.1f}):")
    for i, c in enumerate(counts):
        print(f"  {bins_edges[i]:.0f}-{bins_edges[i+1]:.0f}: {c}")

run_time_histogram(doc, 'Cell window 04')


